package io.github.borderarea01.znote;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import java.io.*;import java.net.*;import org.json.*;

/** Touch actual :capture windows against a disposable server; never user network settings. */
final class CatalogueSmoke {
    final Instrumentation test;final Context context;final UiAutomation ui;
    CatalogueSmoke(Instrumentation test){this.test=test;context=test.getTargetContext();ui=test.getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);android.accessibilityservice.AccessibilityServiceInfo info=ui.getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;ui.setServiceInfo(info);}
    void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    byte[] all(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[2048];int n;while((n=in.read(block))!=-1)out.write(block,0,n);return out.toByteArray();}
    String shell(String code)throws Exception{try(ParcelFileDescriptor fd=ui.executeShellCommand(code);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){return new String(all(in),java.nio.charset.StandardCharsets.UTF_8);}}
    JSONObject control(String mode)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://10.0.2.2:3749/test/control?mode="+mode).openConnection(Proxy.NO_PROXY);try(InputStream in=c.getInputStream()){return new JSONObject(new String(all(in),java.nio.charset.StandardCharsets.UTF_8));}finally{c.disconnect();}}
    AccessibilityNodeInfo find(AccessibilityNodeInfo node,String value){if(node==null)return null;if(node.isVisibleToUser()&&(value.equals(String.valueOf(node.getText()))||value.equals(String.valueOf(node.getContentDescription()))))return AccessibilityNodeInfo.obtain(node);for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo child=node.getChild(i);if(child==null)continue;AccessibilityNodeInfo match=find(child,value);child.recycle();if(match!=null)return match;}return null;}
    AccessibilityNodeInfo node(String value,long wait)throws Exception{long end=SystemClock.uptimeMillis()+wait;do{for(AccessibilityWindowInfo window:ui.getWindows()){AccessibilityNodeInfo root=window.getRoot();if(root==null)continue;AccessibilityNodeInfo hit=find(root,value);root.recycle();if(hit!=null)return hit;}Thread.sleep(70);}while(SystemClock.uptimeMillis()<end);throw new AssertionError("Missing control: "+value);}
    void tap(String value)throws Exception{AccessibilityNodeInfo n=node(value,8000);check(n.isEnabled(),"Disabled control: "+value);Rect r=new Rect();n.getBoundsInScreen(r);n.recycle();long time=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent event=MotionEvent.obtain(time,SystemClock.uptimeMillis(),action,r.centerX(),r.centerY(),0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(ui.injectInputEvent(event,true),"Touch failed");event.recycle();if(action==MotionEvent.ACTION_DOWN)Thread.sleep(45);}Thread.sleep(200);}
    void shot(String name)throws Exception{Bitmap image=ui.takeScreenshot();try(FileOutputStream out=context.openFileOutput("catalogue-"+name+".png",0)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    void open(String text)throws Exception{context.startActivity(new Intent(context,FloatingShareActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra(Intent.EXTRA_TEXT,text).putExtra("selected_collection","photo"));node(text,3000).recycle();node("保存到知识库",1000).recycle();}
    void close()throws Exception{tap("收起采集面板");Thread.sleep(150);}
    void enabledSave()throws Exception{AccessibilityNodeInfo n=node("保存到知识库",1000);check(n.isEnabled(),"Cached form must allow saving");n.recycle();}
    void stream(String text){Bundle update=new Bundle();update.putString("stream","\n"+text+"\n");test.sendStatus(0,update);}
    void run(){Bundle result=new Bundle();try{
        check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"This test is emulator-only");
        context.getSharedPreferences("MainActivity",0).edit().clear().putString("origin","http://10.0.2.2:3749").commit();context.getSharedPreferences("CaptureAuthorization",0).edit().clear().putString(android.net.Uri.encode("http://10.0.2.2:3749"),"zn_"+"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc").commit();
        control("online");open("https://example.test/first");node("知识库列表已更新",16000).recycle();tap("摄影参考");tap("摄影参考");close();int lists=control("hang").getInt("lists");
        long started=SystemClock.uptimeMillis();open("https://example.test/save-while-refreshing");enabledSave();check(SystemClock.uptimeMillis()-started<2500,"Cache display waited for network");check(control("hang").getInt("lists")==lists,"Opening cached form performed a list request");tap("刷新知识库列表");tap("摄影参考");tap("建模学习");enabledSave();shot("cached-during-outage");tap("保存到知识库");
        JSONObject progress=control("hang");check(progress.getInt("posts")==1,"Refresh blocked save queue");check(progress.getJSONArray("requests").getJSONObject(0).getString("collection_id").equals("models"),"Selected cached ID lost");
        stream("save while refreshing passed; reopen retained form");open("https://example.test/keep-this-link");Thread.sleep(14500);control("unavailable");tap("刷新知识库列表");node("刷新失败（HTTP 503），缓存已保留",16000).recycle();enabledSave();node("https://example.test/keep-this-link",1000).recycle();shot("refresh-failed");
        stream("503 retained cached options");control("updated");tap("刷新知识库列表");node("知识库列表已更新",16000).recycle();tap("摄影参考");tap("模型资料");check(control("updated").getInt("lists")>=lists+4,"GET retry was not exercised");
        stream("manual refresh updated names");int before=control("unauthorized").getInt("lists");tap("刷新知识库列表");node("授权已失效，请打开 ZNote 登录；缓存和链接已保留",16000).recycle();check(control("unauthorized").getInt("lists")==before+1,"Authorization error retried");enabledSave();
        control("lost-write");tap("保存到知识库");node("重试保存",16000).recycle();node("https://example.test/keep-this-link",1000).recycle();shot("save-retry");JSONObject uncertain=control("online");check(uncertain.getInt("jobs")==2,"Uncertain write created duplicate jobs");tap("重试保存");Thread.sleep(400);check(control("online").getInt("jobs")==2,"Retry changed request identity");
        stream("uncertain write retry deduplicated");open("https://example.test/cache-after-restart");close();String pid=shell("pidof "+context.getPackageName()+":capture").trim();check(pid.matches("[0-9]+"),"Capture process not found");shell("run-as "+context.getPackageName()+" kill "+pid);Thread.sleep(250);lists=control("hang").getInt("lists");open("https://example.test/cache-after-restart");enabledSave();tap("摄影参考");node("模型资料",2000).recycle();shell("input keyevent 4");check(control("hang").getInt("lists")==lists,"Process restart lost persistent cache");shot("persistent-cache");tap("摄影参考");tap("模型资料");control("removed");tap("刷新知识库列表");node("知识库列表已更新",16000).recycle();node("上次选择的知识库（请刷新确认）",1000).recycle();int saved=control("removed").getInt("posts");tap("保存到知识库");node("所选知识库已不存在，请重新选择；链接已保留",8000).recycle();check(control("removed").getInt("posts")==saved,"Deleted library silently fell back");close();context.getSharedPreferences("MainActivity",0).edit().putString("origin","http://10.0.2.2:3750").commit();open("https://example.test/changed-server");tap("保存到知识库");node("服务器连接已变更，请刷新知识库列表后再保存；链接已保留",10000).recycle();check(control("removed").getInt("posts")==saved,"Stale server cache submitted");shot("changed-server");close();context.getSharedPreferences("MainActivity",0).edit().putString("origin","http://10.0.2.2:3749").commit();
        stream("Cache opens without list requests; refresh failure/retry, unauthorized no-loop, save during refresh, stable write ID, process restart and actual touch PASS");result.putString("stream","\nZNOTE_CATALOGUE_CACHE_PASS\n");test.finish(Activity.RESULT_OK,result);
    }catch(Throwable e){try{shot("failure");}catch(Exception ignored){}result.putString("stream","\nZNOTE_CATALOGUE_CACHE_FAIL: "+e+"\n");test.finish(Activity.RESULT_CANCELED,result);}}
}
